('art-nga-95659','artwork','GEN','{"id":"art-nga-95659","title":"人間の堕罪","summary":"アダムとエバが禁じられた実を分かち合う場面です。動物や身体の配置は画家の構成であり、本文の細部をそのまま再現した記録ではありません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"GEN","start":{"chapter":3,"verse":1},"end":{"chapter":3,"verse":6}}],"spoilerEnd":{"book":"GEN","chapter":3,"verse":6},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-95659","title":"The Fall of Man","url":"https://www.nga.gov/artworks/95659-fall-man","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Hendrick Goltzius","yearLabel":"1616","collection":"National Gallery of Art, Washington · Patrons'' Permanent Fund · 1996.34.1","objectUrl":"https://www.nga.gov/artworks/95659-fall-man","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/7687de47-8722-4522-982d-095d666cacd8/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Hendrick Goltzius, The Fall of Man, 1616. National Gallery of Art, Washington, 1996.34.1. Patrons'' Permanent Fund. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-111718','artwork','GEN','{"id":"art-nga-111718","title":"アダムとエバへの叱責","summary":"問いかける神に対し、アダムがエバを、エバが蛇を指し示します。指さしによる責任転嫁の表現を、創世記の問答と比べて見ます。神の姿は絵画による可視化です。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"GEN","start":{"chapter":3,"verse":9},"end":{"chapter":3,"verse":13}}],"spoilerEnd":{"book":"GEN","chapter":3,"verse":13},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-111718","title":"The Rebuke of Adam and Eve","url":"https://www.nga.gov/artworks/111718-rebuke-adam-and-eve","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Domenichino","yearLabel":"1626","collection":"National Gallery of Art, Washington · Patrons'' Permanent Fund · 2000.3.1","objectUrl":"https://www.nga.gov/artworks/111718-rebuke-adam-and-eve","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/3c055a39-8158-4498-9178-74147a5fd385/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Domenichino, The Rebuke of Adam and Eve, 1626. National Gallery of Art, Washington, 2000.3.1. Patrons'' Permanent Fund. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-70986','artwork','GEN','{"id":"art-nga-70986","title":"楽園を追われるアダムとエバ","summary":"アダムとエバがエデンを去る場面です。天使や光の劇的な配置は、追放の物語を伝えるための美術表現として見ます。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"GEN","start":{"chapter":3,"verse":22},"end":{"chapter":3,"verse":24}}],"spoilerEnd":{"book":"GEN","chapter":3,"verse":24},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-70986","title":"The Expulsion of Adam and Eve from Paradise","url":"https://www.nga.gov/artworks/70986-expulsion-adam-and-eve-paradise","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Benjamin West","yearLabel":"1791","collection":"National Gallery of Art, Washington · Avalon Fund and Patrons'' Permanent Fund · 1989.12.1","objectUrl":"https://www.nga.gov/artworks/70986-expulsion-adam-and-eve-paradise","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/19fdd027-46d8-46d2-8806-d8de9ea9d557/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Benjamin West, The Expulsion of Adam and Eve from Paradise, 1791. National Gallery of Art, Washington, 1989.12.1. Avalon Fund and Patrons'' Permanent Fund. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-74281','artwork','GEN','{"id":"art-nga-74281","title":"動物を箱舟へ導くノア","summary":"ノアと動物たちが箱舟へ向かう場面です。多様な動物を集めた構図は画家の表現で、動物に関する律法を描いた作品ではありません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"GEN","start":{"chapter":7,"verse":7},"end":{"chapter":7,"verse":9}}],"spoilerEnd":{"book":"GEN","chapter":7,"verse":9},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-74281","title":"Noah Leading the Animals into the Ark","url":"https://www.nga.gov/artworks/74281-noah-leading-animals-ark","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Giovanni Benedetto Castiglione","yearLabel":"c. 1645","collection":"National Gallery of Art, Washington · Partial Gift of Gilbert Butler, in Honor of the 50th Anniversary of the National Gallery of Art · 1991.221.1","objectUrl":"https://www.nga.gov/artworks/74281-noah-leading-animals-ark","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/a0e6a30b-2189-4544-970f-6c03619ba97f/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Giovanni Benedetto Castiglione, Noah Leading the Animals into the Ark, c. 1645. National Gallery of Art, Washington, 1991.221.1. Partial Gift of Gilbert Butler, in Honor of the 50th Anniversary of the National Gallery of Art. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-45640','artwork','GEN','{"id":"art-nga-45640","title":"アブラハムとメルキゼデクの出会い","summary":"パンとぶどう酒を携えたメルキゼデクがアブラムを祝福する場面です。壮麗な衣装や建築は制作時代の表現を含み、古代の風景を復元したものではありません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"GEN","start":{"chapter":14,"verse":18},"end":{"chapter":14,"verse":20}}],"spoilerEnd":{"book":"GEN","chapter":14,"verse":20},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-45640","title":"The Meeting of Abraham and Melchizedek","url":"https://www.nga.gov/artworks/45640-meeting-abraham-and-melchizedek","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Sir Peter Paul Rubens","yearLabel":"c. 1626","collection":"National Gallery of Art, Washington · Gift of Syma Busiel · 1958.4.1","objectUrl":"https://www.nga.gov/artworks/45640-meeting-abraham-and-melchizedek","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/5b1fe0fa-1bad-4820-a77e-586d8cfcd481/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Sir Peter Paul Rubens, The Meeting of Abraham and Melchizedek, c. 1626. National Gallery of Art, Washington, 1958.4.1. Gift of Syma Busiel. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-cma-1937-577','artwork','GEN','{"id":"art-cma-1937-577","title":"イサクの犠牲","summary":"刀を上げるアブラハムを天使が制止する場面です。左背景には代わりの犠牲となる雄羊も見えます。身振りと緊張した身体表現を、本文の呼びかけと応答に照らして見ます。章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"GEN","start":{"chapter":22,"verse":9},"end":{"chapter":22,"verse":13}}],"spoilerEnd":{"book":"GEN","chapter":22,"verse":13},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"cma-1937.577","title":"The Sacrifice of Isaac","url":"https://www.clevelandart.org/art/1937.577","publisher":"Cleveland Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.clevelandart.org/open-access","publisher":"Cleveland Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Andrea del Sarto","yearLabel":"c. 1527","collection":"Cleveland Museum of Art · Delia E. Holden and L. E. Holden Funds · 1937.577","objectUrl":"https://www.clevelandart.org/art/1937.577","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://www.clevelandart.org/_next/image?url=https%3A%2F%2Fpiction.clevelandart.org%2Fcma%2Fump.di%3Fe%3DCE5203FBF2EFABBFE718051F7ADF39285EDA6A99769858B438E11E8779ABBEA9%26s%3D24247294%26se%3D116628280%26v%3D3%26f%3D%255Cd6560%255Cu354265604%255C1937.577_o2.jpg&w=1920&q=75","rights":"public-domain","rightsUrl":"https://www.clevelandart.org/open-access","attribution":"Andrea del Sarto, The Sacrifice of Isaac, c. 1527. Cleveland Museum of Art, 1937.577. Delia E. Holden and L. E. Holden Funds. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-cma-1925-30','artwork','GEN','{"id":"art-cma-1925-30","title":"牢獄で夢を解くヨセフ","summary":"ヨセフが献酌官と料理官の夢を解き明かす場面です。ヨセフ自身が夢を語る創世記37章とは区別します。作者表記の「ルーカス・ファン・レイデンに基づく」を保持しています。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"GEN","start":{"chapter":40,"verse":5},"end":{"chapter":40,"verse":19}}],"spoilerEnd":{"book":"GEN","chapter":40,"verse":19},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"cma-1925.30","title":"Joseph Interprets the Dreams in Prison","url":"https://www.clevelandart.org/art/1925.30","publisher":"Cleveland Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.clevelandart.org/open-access","publisher":"Cleveland Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"after Lucas van Leyden","yearLabel":"1512","collection":"Cleveland Museum of Art · Gift of Ralph King · 1925.30","objectUrl":"https://www.clevelandart.org/art/1925.30","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://www.clevelandart.org/_next/image?url=https%3A%2F%2Fpiction.clevelandart.org%2Fcma%2Fump.di%3Fe%3D39134CEFB1508F7326988D388FD81F8D6B50A99B3EBE65FBA1AB3D690BFF8CD2%26s%3D24247294%26se%3D399313166%26v%3D4%26f%3D1925.30_o2.jpg&w=1920&q=75","rights":"public-domain","rightsUrl":"https://www.clevelandart.org/open-access","attribution":"after Lucas van Leyden, Joseph Interprets the Dreams in Prison, 1512. Cleveland Museum of Art, 1925.30. Gift of Ralph King. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-45','artwork','EXO','{"id":"art-nga-45","title":"モーセの発見","summary":"ファラオの娘が幼いモーセを見つける場面です。衣服や集う人々の描写にはヴェネツィアの画家の想像が入り、本文の歴史的な装束を示す資料ではありません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"EXO","start":{"chapter":2,"verse":5},"end":{"chapter":2,"verse":9}}],"spoilerEnd":{"book":"EXO","chapter":2,"verse":9},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-45","title":"The Finding of Moses","url":"https://www.nga.gov/artworks/45-finding-moses","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Veronese","yearLabel":"c. 1581/1582","collection":"National Gallery of Art, Washington · Andrew W. Mellon Collection · 1937.1.38","objectUrl":"https://www.nga.gov/artworks/45-finding-moses","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/7ef08b06-e4ff-49e5-8c13-f79dd0b1a872/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Veronese, The Finding of Moses, c. 1581/1582. National Gallery of Art, Washington, 1937.1.38. Andrew W. Mellon Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-11362','artwork','1SA','{"id":"art-nga-11362","title":"サウル王にゴリアトの首を示すダビデ","summary":"ダビデがゴリアトの首を持ってサウルの前に来る場面です。戦闘そのものではなく、その後の対面を描く素描です。首の描写を含みます。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"1SA","start":{"chapter":17,"verse":57},"end":{"chapter":17,"verse":58}}],"spoilerEnd":{"book":"1SA","chapter":17,"verse":58},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-11362","title":"David Offering the Head of Goliath to King Saul","url":"https://www.nga.gov/artworks/11362-david-offering-head-goliath-king-saul","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Bartolomeo Biscaino","yearLabel":"1650s","collection":"National Gallery of Art, Washington · Rosenwald Collection · 1943.3.8863","objectUrl":"https://www.nga.gov/artworks/11362-david-offering-head-goliath-king-saul","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/87c11b93-7497-484a-a691-36e87d2fa952/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Bartolomeo Biscaino, David Offering the Head of Goliath to King Saul, 1650s. National Gallery of Art, Washington, 1943.3.8863. Rosenwald Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-435769','artwork','1KI','{"id":"art-met-435769","title":"ソロモンの裁き","summary":"子を二つに分けるという王の命令に、母親が子の命を守ろうと応じる場面です。劇的な身振りは裁きの意味を可視化する画家の表現です。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"1KI","start":{"chapter":3,"verse":23},"end":{"chapter":3,"verse":27}}],"spoilerEnd":{"book":"1KI","chapter":3,"verse":27},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-435769","title":"The Judgment of Solomon","url":"https://www.metmuseum.org/art/collection/search/435769","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Leonaert Bramer","yearLabel":"1640s","collection":"The Metropolitan Museum of Art · Gift of National Surety Company, 1911 · 11.73","objectUrl":"https://www.metmuseum.org/art/collection/search/435769","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/ep/web-large/DP145897.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"Leonaert Bramer, The Judgment of Solomon, 1640s. The Metropolitan Museum of Art, 11.73. Gift of National Surety Company, 1911. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-cma-2005-145-72-a','artwork','1KI','{"id":"art-cma-2005-145-72-a","title":"からすに養われるエリヤ","summary":"川辺のエリヤにからすが食物を運ぶ場面です。ムガル朝インドで制作された写本挿絵で、列王記上19章の天使による食事とは別の出来事です。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"1KI","start":{"chapter":17,"verse":4},"end":{"chapter":17,"verse":6}}],"spoilerEnd":{"book":"1KI","chapter":17,"verse":6},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"cma-2005.145.72.a","title":"A raven brings food to Elijah (folio 72 recto), from a Mirror of Holiness (Mir’at al-quds) of Father Jerome Xavier,","url":"https://www.clevelandart.org/art/2005.145.72.a","publisher":"Cleveland Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.clevelandart.org/open-access","publisher":"Cleveland Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Unknown artist; Mughal India, Allahabad, made for Prince Salim (1569–1627)","yearLabel":"1602–4","collection":"Cleveland Museum of Art · John L. Severance Fund · 2005.145.72.a","objectUrl":"https://www.clevelandart.org/art/2005.145.72.a","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://www.clevelandart.org/_next/image?url=https%3A%2F%2Fpiction.clevelandart.org%2Fcma%2Fump.di%3Fe%3D6C05D6D290ADBAA8B1DEB53B4B5E4D8A9132F1942D1FE774D3900D02E29B96ED%26s%3D24247294%26se%3D116628280%26v%3D1%26f%3D%255Cd7968%255Cu237579684%255C2005.145.72.a_o2.jpg&w=1920&q=75","rights":"public-domain","rightsUrl":"https://www.clevelandart.org/open-access","attribution":"Unknown artist; Mughal India, Allahabad, made for Prince Salim (1569–1627), A raven brings food to Elijah (folio 72 recto), from a Mirror of Holiness (Mir’at al-quds) of Father Jerome Xavier,, 1602–4. Cleveland Museum of Art, 2005.145.72.a. John L. Severance Fund. CC0.","checkedAt":"2026-10-18