('art-cma-1951-337','artwork','1KI','{"id":"art-cma-1951-337","title":"エリヤとサレプタのやもめ","summary":"枝を拾うやもめとエリヤの出会いを描いたステンドグラスです。後の息子の蘇生を描く場面とは区別し、出会いの箇所に対応させています。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"1KI","start":{"chapter":17,"verse":10},"end":{"chapter":17,"verse":12}}],"spoilerEnd":{"book":"1KI","chapter":17,"verse":12},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"cma-1951.337","title":"Elijah and the Widow of Zarephath","url":"https://www.clevelandart.org/art/1951.337","publisher":"Cleveland Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.clevelandart.org/open-access","publisher":"Cleveland Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Unknown artist; North Netherlands, 16th century","yearLabel":"c. 1525","collection":"Cleveland Museum of Art · Bequest of William G. Mather · 1951.337","objectUrl":"https://www.clevelandart.org/art/1951.337","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://www.clevelandart.org/_next/image?url=https%3A%2F%2Fpiction.clevelandart.org%2Fcma%2Fump.di%3Fe%3D7488BA071F4E2D50C0BD2A9EF60F0793885D434112F6A79FEFAB49A6C09AB5D4%26s%3D24247294%26se%3D399313166%26v%3D0%26f%3D1951.337_o2.jpg&w=1920&q=75","rights":"public-domain","rightsUrl":"https://www.clevelandart.org/open-access","attribution":"Unknown artist; North Netherlands, 16th century, Elijah and the Widow of Zarephath, c. 1525. Cleveland Museum of Art, 1951.337. Bequest of William G. Mather. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-cma-1965-239','artwork','JON','{"id":"art-cma-1965-239","title":"とうごまの下のヨナ","summary":"ニネベの外で植物の陰に休むヨナの大理石彫刻です。まだ茂る植物を描き、後に枯れる場面までは対応させていません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"JON","start":{"chapter":4,"verse":5},"end":{"chapter":4,"verse":6}}],"spoilerEnd":{"book":"JON","chapter":4,"verse":6},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"cma-1965.239","title":"Jonah Under the Gourd Vine","url":"https://www.clevelandart.org/art/1965.239","publisher":"Cleveland Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.clevelandart.org/open-access","publisher":"Cleveland Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Unknown artist; Anatolia, late Roman-early Christian","yearLabel":"280–90 CE","collection":"Cleveland Museum of Art · John L. Severance Fund · 1965.239","objectUrl":"https://www.clevelandart.org/art/1965.239","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://www.clevelandart.org/_next/image?url=https%3A%2F%2Fpiction.clevelandart.org%2Fcma%2Fump.di%3Fe%3D7B9170A49DFB8CCE896EAE25B7591C7662981D5100FC21DB3A37EEAE556AA7FC%26s%3D24247294%26se%3D116628280%26v%3D7%26f%3D1965.239_o2.jpg&w=1920&q=75","rights":"public-domain","rightsUrl":"https://www.clevelandart.org/open-access","attribution":"Unknown artist; Anatolia, late Roman-early Christian, Jonah Under the Gourd Vine, 280–90 CE. Cleveland Museum of Art, 1965.239. John L. Severance Fund. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-9956','artwork','GEN','{"id":"art-nga-9956","title":"天使たちをもてなすアブラハム","summary":"アブラハムが三人の訪問者を迎えて食事を用意する場面です。後に続くイサク誕生の告知とは区別し、もてなしの場面に対応させます。天使の姿は画家による解釈です。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"GEN","start":{"chapter":18,"verse":1},"end":{"chapter":18,"verse":8}}],"spoilerEnd":{"book":"GEN","chapter":18,"verse":8},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-9956","title":"Abraham Entertaining the Angels","url":"https://www.nga.gov/artworks/9956-abraham-entertaining-angels","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Rembrandt van Rijn","yearLabel":"1656","collection":"National Gallery of Art, Washington · Rosenwald Collection · 1943.3.7160","objectUrl":"https://www.nga.gov/artworks/9956-abraham-entertaining-angels","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/2d70a595-5850-4887-951e-7eede361f462/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Rembrandt van Rijn, Abraham Entertaining the Angels, 1656. National Gallery of Art, Washington, 1943.3.7160. Rosenwald Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-53142','artwork','EXO','{"id":"art-nga-53142","title":"岩を打つモーセ","summary":"モーセがホレブの岩を打ち、水が流れ出す場面です。所蔵館が出エジプト記のホレブと特定しているため、民数記20章の岩打ちとは混同しません。多くの人物や動物の配置は画家の構成です。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"EXO","start":{"chapter":17,"verse":5},"end":{"chapter":17,"verse":6}}],"spoilerEnd":{"book":"EXO","chapter":17,"verse":6},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-53142","title":"Moses Striking the Rock","url":"https://www.nga.gov/artworks/53142-moses-striking-rock","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Joachim Anthonisz Wtewael","yearLabel":"1624","collection":"National Gallery of Art, Washington · Ailsa Mellon Bruce Fund · 1972.11.1","objectUrl":"https://www.nga.gov/artworks/53142-moses-striking-rock","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/45dc7208-ccc2-4e0c-bb61-fc7497ce13b5/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Joachim Anthonisz Wtewael, Moses Striking the Rock, 1624. National Gallery of Art, Washington, 1972.11.1. Ailsa Mellon Bruce Fund. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-321','artwork','EXO','{"id":"art-nga-321","title":"金の子牛の礼拝","summary":"金を集める場面、子牛の礼拝と宴、山で石板を受けるモーセを組み合わせた絵です。中心場面は出エジプト32章、石板授与は31:18に対応します。複数の時点を一枚に構成した作品です。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"EXO","start":{"chapter":31,"verse":18},"end":{"chapter":31,"verse":18}},{"book":"EXO","start":{"chapter":32,"verse":1},"end":{"chapter":32,"verse":6}}],"spoilerEnd":{"book":"EXO","chapter":32,"verse":6},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-321","title":"The Worship of the Golden Calf","url":"https://www.nga.gov/artworks/321-worship-golden-calf","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Italian 16th Century","yearLabel":"c. 1594","collection":"National Gallery of Art, Washington · Samuel H. Kress Collection · 1939.1.180","objectUrl":"https://www.nga.gov/artworks/321-worship-golden-calf","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/9d65469d-7f64-4f58-8123-527ba3865458/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Italian 16th Century, The Worship of the Golden Calf, c. 1594. National Gallery of Art, Washington, 1939.1.180. Samuel H. Kress Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-1145','artwork','1SA','{"id":"art-nga-1145","title":"ゴリアトの首を伴うダビデ","summary":"ダビデの石投げと、倒されたゴリアトの首を同じ構図に描きます。勝利に至る複数の時点を組み合わせた表現であり、一瞬の出来事を写したものではありません。首の描写を含みます。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"1SA","start":{"chapter":17,"verse":49},"end":{"chapter":17,"verse":51}}],"spoilerEnd":{"book":"1SA","chapter":17,"verse":51},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-1145","title":"David with the Head of Goliath","url":"https://www.nga.gov/artworks/1145-david-head-goliath","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Andrea del Castagno","yearLabel":"c. 1450/1455","collection":"National Gallery of Art, Washington · Widener Collection · 1942.9.8","objectUrl":"https://www.nga.gov/artworks/1145-david-head-goliath","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/f6dc7861-6bc3-4712-a814-43804f3ecca0/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Andrea del Castagno, David with the Head of Goliath, c. 1450/1455. National Gallery of Art, Washington, 1942.9.8. Widener Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-41685','artwork','2KI','{"id":"art-nga-41685","title":"火の戦車とともに昇るエリヤ","summary":"エリシャの見守る前でエリヤが天へ上げられる場面です。火の戦車や光の配置は本文をもとにした画家の可視化であり、出来事の記録写真のようには扱いません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"2KI","start":{"chapter":2,"verse":11},"end":{"chapter":2,"verse":12}}],"spoilerEnd":{"book":"2KI","chapter":2,"verse":12},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-41685","title":"Elijah Taken Up in a Chariot of Fire","url":"https://www.nga.gov/artworks/41685-elijah-taken-chariot-fire","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices#open-access","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Giuseppe Angeli","yearLabel":"c. 1740/1755","collection":"National Gallery of Art, Washington · Samuel H. Kress Collection · 1952.5.70","objectUrl":"https://www.nga.gov/artworks/41685-elijah-taken-chariot-fire","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/aa13972f-935a-4f1f-aad2-ba825e323cd3/full/!600,600/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices#open-access","attribution":"Giuseppe Angeli, Elijah Taken Up in a Chariot of Fire, c. 1740/1755. National Gallery of Art, Washington, 1952.5.70. Samuel H. Kress Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-642876','artwork','GEN','{"id":"art-met-642876","title":"再会するエサウとヤコブ","summary":"エサウとヤコブが再会して抱き合う場面の木口木版です。生まれながらの権利や祝福をめぐる以前の出来事とは区別します。ダルジール兄弟がワッツの原画に基づいて制作しました。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"GEN","start":{"chapter":33,"verse":1},"end":{"chapter":33,"verse":4}}],"spoilerEnd":{"book":"GEN","chapter":33,"verse":4},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-642876","title":"Esau Meeting Jacob, from \"Dalziels'' Bible Gallery\"","url":"https://www.metmuseum.org/art/collection/search/642876","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Dalziel Brothers, after George Frederic Watts","yearLabel":"1881","collection":"The Metropolitan Museum of Art · Anonymous Gift, 1926 · 26.99.1(21)","objectUrl":"https://www.metmuseum.org/art/collection/search/642876","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/dp/web-large/DP835809.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"Dalziel Brothers, after George Frederic Watts, Esau Meeting Jacob, from \"Dalziels'' Bible Gallery\", 1881. The Metropolitan Museum of Art, 26.99.1(21). Anonymous Gift, 1926. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-370643','artwork','GEN','{"id":"art-met-370643","title":"夢を語るヨセフ","summary":"ヨセフが自分の夢を兄弟と父に話す場面のエッチングです。牢獄やファラオの前で他者の夢を解く後の場面ではありません。人物の表情と配置は画家の構成です。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"GEN","start":{"chapter":37,"verse":5},"end":{"chapter":37,"verse":11}}],"spoilerEnd":{"book":"GEN","chapter":37,"verse":11},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-370643","title":"Joseph Telling His Dreams","url":"https://www.metmuseum.org/art/collection/search/370643","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Rembrandt (Rembrandt van Rijn)","yearLabel":"1638","collection":"The Metropolitan Museum of Art · Bequest of Harry G. Friedman, 1965 · 66.521.68","objectUrl":"https://www.metmuseum.org/art/collection/search/370643","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/dp/web-large/DP814540.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"Rembrandt (Rembrandt van Rijn), Joseph Telling His Dreams, 1638. The Metropolitan Museum of Art, 66.521.68. Bequest of Harry G. Friedman, 1965. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-13200','artwork','DEU','{"id":"art-met-13200","title":"約束の地を示されるモーセ","summary":"モーセが自らは入らない約束の地を示される場面です。風景や神の姿を表す構図には画家の想像が含まれ、ネボ山からの景観を実測した資料ではありません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"DEU","start":{"chapter":34,"verse":1},"end":{"chapter":34,"verse":4}}],"spoilerEnd":{"book":"DEU","chapter":34,"verse":4},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-13200","title":"Moses Shown the Promised Land","url":"https://www.metmuseum.org/art/collection/search/13200","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Benjamin West","yearLabel":"1801","collection":"The Metropolitan Museum of Art · Gift of Mr. and Mrs. James W. Fosburgh, by exchange, 1969 · 69.73","objectUrl":"https://www.metmuseum.org/art/collection/search/13200","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/ad/web-large/ap69.73.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"Benjamin West, Moses Shown the Promised Land, 1801. The Metropolitan Museum of Art, 69.73. Gift of Mr. and Mrs. James W. Fosburgh, by exchange, 1969. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-459016','artwork','LUK','{"id":"art-met-459016","title":"受胎告知","summary":"ガブリエルがマリアにイエスの誕生を告げる場面です。建築空間や金の装飾は画家の表現であり、本文の細部とは区別して見ます。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"LUK","start":{"chapter":1,"verse":26},"end":{"chapter":1,"verse":38}}],"spoilerEnd":{"book":"LUK","chapter":1,"verse":38},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-459016","title":"The Annunciation","url":"https://www.metmuseum.org/art/collection/search/459016","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Botticelli (Alessandro di Mariano Filipepi)","yearLabel":"ca. 1490","collection":"The Metropolitan Museum of Art · Robert Lehman Collection, 1975 · 1975.1.74","objectUrl":"https://www.metmuseum.org/art/collection/search/459016","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/rl/web-large/DP267397.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"Botticelli (Alessandro di Mariano Filipepi), The Annunciation, ca. 1490. The Metropolitan Museum of Art, 1975.1.74. Robert Lehman Collection, 1975. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-436570','artwork','LUK','{"id":"art-met-436570","title":"羊飼いの礼拝","summary":"天使の知らせを受けた羊飼いたちが幼子イエスを訪れる場面です。遠景の告知と幼子を囲む人々を一つの構図にまとめています。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"LUK","start":{"chapter":2,"verse":8},"end":{"chapter":2,"verse":20}}],"spoilerEnd":{"book":"LUK","chapter":2,"verse":20},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-436570","title":"The Adoration of the Shepherds","url":"https://www.metmuseum.org/art/collection/search/436570","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"El Greco (Domenikos Theotokopoulos)","yearLabel":"ca. 1605–10","collection":"The Metropolitan Museum of Art · Rogers Fund, 1905 · 05.42","objectUrl":"https://www.metmuseum.org/art/collection/search/436570","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/ep/web-large/DP123919.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"El Greco (Domenikos Theotokopoulos), The Adoration of the Shepherds, ca. 1605–10. The Metropolitan Museum of Art, 05.42. Rogers Fund, 1905. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-437849','artwork','MAT','{"id":"art-met-437849","title":"エジプトへの逃避","summary":"ヨセフ、マリア、幼子イエスがエジプトへ逃れる場面です。移動の仕方や風景は画家が補った表現で、マタイ本文は乗り物を指定していません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"MAT","start":{"chapter":2,"verse":13},"end":{"chapter":2,"verse":15}}],"spoilerEnd":{"book":"MAT","chapter":2,"verse":15},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-437849","title":"The Flight into Egypt","url":"https://www.metmuseum.org/art/collection/search/437849","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Cosmè Tura (Cosimo di Domenico di Bonaventura)","yearLabel":"1470s","collection":"The Metropolitan Museum of Art · The Jules Bache Collection, 1949 · 49.7.17","objectUrl":"https://www.metmuseum.org/art/collection/search/437849","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/ep/web-large/DP-19503-001.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"Cosmè Tura (Cosimo di Domenico di Bonaventura), The Flight into Egypt, 1470s. The Metropolitan Museum of Art, 49.7.17. The Jules Bache Collection, 1949. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-46124','artwork','MAT','{"id":"art-nga-46124","title":"キリストの洗礼","summary":"ヨハネがヨルダン川でイエスに洗礼を授け、鳩が降る場面です。傍らの天使は絵画の伝統的な付加であり、指定箇所の記述と区別します。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"MAT","start":{"chapter":3,"verse":13},"end":{"chapter":3,"verse":17}}],"spoilerEnd":{"book":"MAT","chapter":3,"verse":17},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-46124","title":"The Baptism of Christ","url":"https://www.nga.gov/artworks/46124-baptism-christ","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Juan de Flandes","yearLabel":"c. 1508/1519","collection":"National Gallery of Art, Washington · Samuel H. Kress Collection · 1961.9.25","objectUrl":"https://www.nga.gov/artworks/46124-baptism-christ","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/66fecc33-883c-4cee-b7d3-0633dd17dfd6/full/!800,800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Juan de Flandes, The Baptism of Christ, c. 1508/1519. National Gallery of Art, Washington, 1961.9.25. Samuel H. Kress Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
