('art-nga-34956','artwork','LUK','{"id":"art-nga-34956","title":"放蕩息子の帰還","summary":"帰ってきた息子を父が迎え、着物や指輪や宴の用意が示されます。イエスが語るたとえの挿絵として見ます。イエスの生涯に起きた出来事の絵ではありません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"LUK","start":{"chapter":15,"verse":20},"end":{"chapter":15,"verse":24}}],"spoilerEnd":{"book":"LUK","chapter":15,"verse":24},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-34956","title":"The Return of the Prodigal Son","url":"https://www.nga.gov/artworks/34956-return-prodigal-son","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Bartolomé Esteban Murillo","yearLabel":"1667/1670","collection":"National Gallery of Art, Washington · Gift of the Avalon Foundation · 1948.12.1","objectUrl":"https://www.nga.gov/artworks/34956-return-prodigal-son","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/676fa96e-ad4e-4209-b985-ae0c15f5d902/full/!800,800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Bartolomé Esteban Murillo, The Return of the Prodigal Son, 1667/1670. National Gallery of Art, Washington, 1948.12.1. Gift of the Avalon Foundation. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-459131','artwork','JHN','{"id":"art-met-459131","title":"最後の晩餐：裏切りの告知","summary":"晩餐でイエスが裏切りを告げ、ユダに一切れを渡す場面です。この作品はヨハネの裏切りの告知に対応させ、聖餐制定の直接描写とは扱いません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"JHN","start":{"chapter":13,"verse":21},"end":{"chapter":13,"verse":26}}],"spoilerEnd":{"book":"JHN","chapter":13,"verse":26},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-459131","title":"The Last Supper","url":"https://www.metmuseum.org/art/collection/search/459131","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Ugolino da Siena (Ugolino di Nerio)","yearLabel":"ca. 1325","collection":"The Metropolitan Museum of Art · Robert Lehman Collection, 1975 · 1975.1.7","objectUrl":"https://www.metmuseum.org/art/collection/search/459131","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/rl/web-large/DT3003.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"Ugolino da Siena (Ugolino di Nerio), The Last Supper, ca. 1325. The Metropolitan Museum of Art, 1975.1.7. Robert Lehman Collection, 1975. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-118598','artwork','JHN','{"id":"art-nga-118598","title":"弟子の足を洗うキリスト","summary":"イエスが身をかがめて弟子の足を洗い、ペトロが応じる場面です。室内や衣装は画家の表現であり、洗足の意味は本文の対話とあわせて読みます。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"JHN","start":{"chapter":13,"verse":3},"end":{"chapter":13,"verse":11}}],"spoilerEnd":{"book":"JHN","chapter":13,"verse":11},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-118598","title":"Christ Washing the Disciples'' Feet","url":"https://www.nga.gov/artworks/118598-christ-washing-disciples-feet","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Garofalo","yearLabel":"c. 1520/1525","collection":"National Gallery of Art, Washington · Patrons'' Permanent Fund · 2001.29.1","objectUrl":"https://www.nga.gov/artworks/118598-christ-washing-disciples-feet","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/778cf516-cc6e-46b1-97e7-6e8057ee8ae8/full/!800,800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Garofalo, Christ Washing the Disciples'' Feet, c. 1520/1525. National Gallery of Art, Washington, 2001.29.1. Patrons'' Permanent Fund. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-460','artwork','LUK','{"id":"art-nga-460","title":"ゲツセマネの祈り","summary":"眠る弟子たちの近くでイエスが祈り、天使が寄り添う場面です。天使の描写はルカの伝承に対応します。ルカ22:43–44は訳によって括弧や注記が付く箇所です。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"LUK","start":{"chapter":22,"verse":39},"end":{"chapter":22,"verse":46}}],"spoilerEnd":{"book":"LUK","chapter":22,"verse":46},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-460","title":"The Agony in the Garden","url":"https://www.nga.gov/artworks/460-agony-garden","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Benvenuto di Giovanni","yearLabel":"probably 1491","collection":"National Gallery of Art, Washington · Samuel H. Kress Collection · 1939.1.318","objectUrl":"https://www.nga.gov/artworks/460-agony-garden","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/7cb81e27-9f59-43de-829c-dff8edd3a609/full/!800,800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Benvenuto di Giovanni, The Agony in the Garden, probably 1491. National Gallery of Art, Washington, 1939.1.318. Samuel H. Kress Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-46118','artwork','JHN','{"id":"art-nga-46118","title":"小さな磔刑","summary":"十字架のイエスと、マリア、愛する弟子、マグダラのマリアを描きます。暗い空はルカの受難記事にも通じる副次的要素です。傷の描写を含みます。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"JHN","start":{"chapter":19,"verse":25},"end":{"chapter":19,"verse":30}}],"spoilerEnd":{"book":"JHN","chapter":19,"verse":30},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-46118","title":"The Small Crucifixion","url":"https://www.nga.gov/artworks/46118-small-crucifixion","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Matthias Grünewald","yearLabel":"c. 1511/1520","collection":"National Gallery of Art, Washington · Samuel H. Kress Collection · 1961.9.19","objectUrl":"https://www.nga.gov/artworks/46118-small-crucifixion","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/55182e13-5f28-46e1-af6a-e3cd573ce00f/full/!800,800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Matthias Grünewald, The Small Crucifixion, c. 1511/1520. National Gallery of Art, Washington, 1961.9.19. Samuel H. Kress Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-401','artwork','JHN','{"id":"art-nga-401","title":"キリストの埋葬","summary":"イエスの遺体を墓へ運ぶ場面です。ヨセフとニコデモによる埋葬の記事に対応させます。嘆く人物や道具の配置には美術上の展開が含まれます。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"JHN","start":{"chapter":19,"verse":38},"end":{"chapter":19,"verse":42}}],"spoilerEnd":{"book":"JHN","chapter":19,"verse":42},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-401","title":"The Entombment of Christ","url":"https://www.nga.gov/artworks/401-entombment-christ","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Fra Angelico","yearLabel":"c. 1450","collection":"National Gallery of Art, Washington · Samuel H. Kress Collection · 1939.1.260","objectUrl":"https://www.nga.gov/artworks/401-entombment-christ","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/45fa82c0-494f-489b-9062-9b62c842008c/full/!800,800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Fra Angelico, The Entombment of Christ, c. 1450. National Gallery of Art, Washington, 1939.1.260. Samuel H. Kress Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-41670','artwork','MAT','{"id":"art-nga-41670","title":"キリストの復活","summary":"墓と兵士の上に立つキリストによって復活を表す作品です。福音書はキリストが墓から出る瞬間を叙述していません。マタイ28章との対応は主題上のもので、天使と番兵の記述の文字どおりの再現ではありません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"MAT","start":{"chapter":28,"verse":1},"end":{"chapter":28,"verse":6}}],"spoilerEnd":{"book":"MAT","chapter":28,"verse":6},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"thematic","provenance":[{"id":"nga-41670","title":"The Resurrection","url":"https://www.nga.gov/artworks/41670-resurrection","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Benvenuto di Giovanni","yearLabel":"probably 1491","collection":"National Gallery of Art, Washington · Samuel H. Kress Collection · 1952.5.55","objectUrl":"https://www.nga.gov/artworks/41670-resurrection","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/f1218b9a-8b6d-4936-9fd9-3066f1951443/full/!800,800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Benvenuto di Giovanni, The Resurrection, probably 1491. National Gallery of Art, Washington, 1952.5.55. Samuel H. Kress Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-437871','artwork','LUK','{"id":"art-met-437871","title":"エマオの晩餐","summary":"パンを裂くイエスを見て、弟子たちが復活した主だと気づく場面です。食卓の配置や表情は画家の構成として、ルカの認識の物語と比べて見ます。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"LUK","start":{"chapter":24,"verse":28},"end":{"chapter":24,"verse":35}}],"spoilerEnd":{"book":"LUK","chapter":24,"verse":35},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-437871","title":"The Supper at Emmaus","url":"https://www.metmuseum.org/art/collection/search/437871","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Velázquez (Diego Rodríguez de Silva y Velázquez)","yearLabel":"1622–23","collection":"The Metropolitan Museum of Art · Bequest of Benjamin Altman, 1913 · 14.40.631","objectUrl":"https://www.metmuseum.org/art/collection/search/437871","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/ep/web-large/DP120945.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"Velázquez (Diego Rodríguez de Silva y Velázquez), The Supper at Emmaus, 1622–23. The Metropolitan Museum of Art, 14.40.631. Bequest of Benjamin Altman, 1913. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-6785','artwork','ACT','{"id":"art-nga-6785","title":"聖霊降臨","summary":"集まる弟子たちに聖霊が降る場面の木版画です。マリアの同席は伝統的図像と使徒1:14を背景とし、使徒2:1–4では個別に名指されていません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"ACT","start":{"chapter":2,"verse":1},"end":{"chapter":2,"verse":4}}],"spoilerEnd":{"book":"ACT","chapter":2,"verse":4},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-6785","title":"Pentecost","url":"https://www.nga.gov/artworks/6785-pentecost","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Albrecht Dürer","yearLabel":"probably c. 1509/1510","collection":"National Gallery of Art, Washington · Rosenwald Collection · 1943.3.3667","objectUrl":"https://www.nga.gov/artworks/6785-pentecost","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/f1f88964-fab0-492b-86e8-ee1619e0142a/full/!800,800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Albrecht Dürer, Pentecost, probably c. 1509/1510. National Gallery of Art, Washington, 1943.3.3667. Rosenwald Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-815780','artwork','ACT','{"id":"art-met-815780","title":"聖霊降臨：使徒とマリア","summary":"使徒たちとマリアの上に聖霊が現れる場面の版画です。左の寄進者は聖書本文の登場人物ではありません。作者表記にはガウデンツィオ・フェラーリに基づくことを残しています。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"ACT","start":{"chapter":2,"verse":1},"end":{"chapter":2,"verse":4}}],"spoilerEnd":{"book":"ACT","chapter":2,"verse":4},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-815780","title":"The Pentecost, with the Apostles and the Virgin sitting in a circle, the Holy Spirit appearing above them, and a donor kneeling at left","url":"https://www.metmuseum.org/art/collection/search/815780","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Frédéric Horthemels, after Gaudenzio Ferrari","yearLabel":"1729–40","collection":"The Metropolitan Museum of Art · Gift of Harry G. Friedman, 1960 · 60.708(6)","objectUrl":"https://www.metmuseum.org/art/collection/search/815780","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/dp/web-large/DP885751.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"Frédéric Horthemels, after Gaudenzio Ferrari, The Pentecost, with the Apostles and the Virgin sitting in a circle, the Holy Spirit appearing above them, and a donor kneeling at left, 1729–40. The Metropolitan Museum of Art, 60.708(6). Gift of Harry G. Friedman, 1960. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-met-392071','artwork','ACT','{"id":"art-met-392071","title":"神殿の門で足の不自由な人を癒やすペトロとヨハネ","summary":"神殿の門でペトロとヨハネが歩けない男性を癒やす場面です。群衆と建築は版画の構成として見ます。所蔵館の原画像はガラス越しの撮影で、反射が見えることがあります。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"ACT","start":{"chapter":3,"verse":1},"end":{"chapter":3,"verse":10}}],"spoilerEnd":{"book":"ACT","chapter":3,"verse":10},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"met-392071","title":"Peter and John Healing the Cripple at the Gate of the Temple","url":"https://www.metmuseum.org/art/collection/search/392071","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.metmuseum.org/hubs/open-access","publisher":"The Metropolitan Museum of Art","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Rembrandt (Rembrandt van Rijn)","yearLabel":"1659","collection":"The Metropolitan Museum of Art · Bequest of Grace M. Pugh, 1985 · 1986.1180.1363","objectUrl":"https://www.metmuseum.org/art/collection/search/392071","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://images.metmuseum.org/CRDImages/dp/web-large/DP814973.jpg","rights":"public-domain","rightsUrl":"https://www.metmuseum.org/hubs/open-access","attribution":"Rembrandt (Rembrandt van Rijn), Peter and John Healing the Cripple at the Gate of the Temple, 1659. The Metropolitan Museum of Art, 1986.1180.1363. Bequest of Grace M. Pugh, 1985. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-10045','artwork','ACT','{"id":"art-nga-10045","title":"ステファノの殉教","summary":"ひざまずくステファノに人々が石を投げる場面のエッチングです。身振りと群像は画家の構成であり、本文の祈りと応答とあわせて見ます。暴力的な殉教場面を含みます。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"ACT","start":{"chapter":7,"verse":54},"end":{"chapter":7,"verse":60}}],"spoilerEnd":{"book":"ACT","chapter":7,"verse":60},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-10045","title":"The Stoning of Saint Stephen","url":"https://www.nga.gov/artworks/10045-stoning-saint-stephen","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Rembrandt van Rijn","yearLabel":"1635","collection":"National Gallery of Art, Washington · Rosenwald Collection · 1943.3.7249","objectUrl":"https://www.nga.gov/artworks/10045-stoning-saint-stephen","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/253c2bf5-e2a2-49ae-b764-99828a3d8073/full/!800,800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Rembrandt van Rijn, The Stoning of Saint Stephen, 1635. National Gallery of Art, Washington, 1943.3.7249. Rosenwald Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1'),
('art-nga-9908','artwork','ACT','{"id":"art-nga-9908","title":"エチオピアの宦官の洗礼","summary":"旅の途中でフィリポがエチオピアの高官に洗礼を授ける場面です。使徒8:37には写本・翻訳上の相違がありますが、この絵の対応はその節の有無には依存しません。 章節範囲は主題をもとに編集上対応させたものです。","passages":[{"book":"ACT","start":{"chapter":8,"verse":35},"end":{"chapter":8,"verse":39}}],"spoilerEnd":{"book":"ACT","chapter":8,"verse":39},"version":"artwork-reviewed-2026-10-18.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-9908","title":"The Baptism of the Eunuch","url":"https://www.nga.gov/artworks/9908-baptism-eunuch","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"},{"id":"museum-image-rights","title":"所蔵館の画像公開利用方針","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art, Washington","checkedAt":"2026-10-18","license":"citation-only"}],"kind":"artwork","details":{"artist":"Rembrandt van Rijn","yearLabel":"1641","collection":"National Gallery of Art, Washington · Rosenwald Collection · 1943.3.7112","objectUrl":"https://www.nga.gov/artworks/9908-baptism-eunuch","rightsStatement":"所蔵館が当該画像をパブリックドメイン／CC0対象と確認しています。作品画像の利用条件であり、美術館の解説文全体の転載許可を意味しません。","media":{"url":"https://api.nga.gov/iiif/0e7fb9f7-3e1c-48e0-bd09-6e07c4803310/full/!800,800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Rembrandt van Rijn, The Baptism of the Eunuch, 1641. National Gallery of Art, Washington, 1943.3.7112. Rosenwald Collection. CC0.","checkedAt":"2026-10-18"}}}','artwork-reviewed-2026-10-18.1','approved','1') ON CONFLICT(id) DO UPDATE SET kind=excluded.kind,book=excluded.book,data_json=excluded.data_json,version=excluded.version,rights_status=excluded.rights_status,active=excluded.active WHERE public_materials.data_json<>excluded.data_json OR public_materials.version<>excluded.version OR public_materials.rights_status<>excluded.rights_status OR public_materials.active<>excluded.active;
